export function shortestPath(
    graph: Map<string, string[]>,
    start: string,
    goal: string,
): string[] | null {
    const queue = [start];
    const visited = new Set<string>([start]);
    const parent = new Map<string, string>();
    let head = 0;

    while (head < queue.length) {
        const node = queue[head];
        head += 1;
        if (node === goal) {
            return rebuild(parent, start, goal);
        }
        for (const next of graph.get(node) ?? []) {
            if (visited.has(next)) {
                continue;
            }
            visited.add(next);
            parent.set(next, node);
            queue.push(next);
        }
    }

    return null;
}

function rebuild(
    parent: Map<string, string>,
    start: string,
    goal: string,
): string[] {
    const path = [goal];
    let current = goal;
    while (current !== start) {
        const previous = parent.get(current);
        if (previous === undefined) {
            return [];
        }
        path.push(previous);
        current = previous;
    }
    return path.reverse();
}
